 const phys=(pred,change)=>attack('C192.intentCrashUnknown__local.counterexample',true,'physicalPreAckKill',pred,change),batch=r=>r.url.endsWith(':batchUpdate'),docs=r=>r.url.startsWith('https://docs.googleapis.com/')&&!batch(r),drive=r=>r.url.includes('/drive/v3/files/'),normal=(pred,change)=>attack('C192.acknowledged__local.success',false,null,pred,change);
